insert into public.place_programs (id, place_id, source_url, source_checked_date, verification_status, conflict_note, name, description, attendance, cadence, schedule_note, starts_on, ends_on, age_min, age_max, price_note, registration_url, sort_order)
values (md5('PE-002:program:pe002-little-boogles')::uuid, 'PE-002', 'https://www.boogles.app/schedule', '2026-10-24', 'verified', null, 'Little Boogles: Bubbles, Music & Sensory Play', 'A Stay + Play session made for babies and toddlers: sensory play, instruments, scarves, music, movement and bubbles at their own pace, with short Play Partner-led moments of music and bubble play. Relaxed rather than a formal class.', 'with_parent', 'ongoing', 'Two sessions in the week we checked (Monday and Friday)', null, null, null, null, 'Included with regular Stay + Play admission · siblings under 1 free with a paying sibling', 'https://www.boogles.app/schedule', 2);
insert into public.place_programs (id, place_id, source_url, source_checked_date, verification_status, conflict_note, name, description, attendance, cadence, schedule_note, starts_on, ends_on, age_min, age_max, price_note, registration_url, sort_order)
values (md5('PE-002:program:pe002-wonder-club')::uuid, 'PE-002', 'https://www.boogles.app/schedule', '2026-10-24', 'verified', null, 'Wonder Club', 'A playful drop-off session with a hands-on creative activity, imaginative games, movement and time to explore with friends. You stay in Square One.', 'drop_off', 'ongoing', 'Tuesdays in the week we checked', null, null, 2, 6, 'Regular drop-off prices: $25 for 1 hour · $45 for 2 · $60 for 3', 'https://www.boogles.app/schedule', 3);
insert into public.place_programs (id, place_id, source_url, source_checked_date, verification_status, conflict_note, name, description, attendance, cadence, schedule_note, starts_on, ends_on, age_min, age_max, price_note, registration_url, sort_order)
values (md5('PE-002:program:pe002-guided-connection')::uuid, 'PE-002', 'https://www.boogles.app/schedule', '2026-10-24', 'verified', null, 'Guided Connection', 'A gentle, play-based class for little ones who may benefit from extra support, structure and connection, led by a certified early interventionist with more than 15 years in the autism field. Music, movement and sensory play; caregivers join in. Each class stands on its own, so come when it suits you.', 'with_parent', 'ongoing', '1½ hours; Friday morning in the week we checked', null, null, null, 5, '$30 per child · 20% off siblings', 'https://www.boogles.app/schedule', 4);
insert into public.place_programs (id, place_id, source_url, source_checked_date, verification_status, conflict_note, name, description, attendance, cadence, schedule_note, starts_on, ends_on, age_min, age_max, price_note, registration_url, sort_order)
values (md5('PE-002:program:pe002-classes')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'Classes', 'A rotating schedule of classes for ages 0–6, such as music, yoga, art, sensory play and infant massage. Some you join with your child; others are drop-off. Bring a diaper bag; class materials are provided, and babies can feed or be changed whenever they need to.', null, 'ongoing', null, null, null, 0, 6, '$25 per class, or 1 bundle hour · 6-class bundle $135', 'https://www.boogles.app/schedule', 5);
insert into public.place_programs (id, place_id, source_url, source_checked_date, verification_status, conflict_note, name, description, attendance, cadence, schedule_note, starts_on, ends_on, age_min, age_max, price_note, registration_url, sort_order)
values (md5('PE-002:program:pe002-camps')::uuid, 'PE-002', 'https://www.boogles.ca/services/', '2026-10-24', 'verified', null, 'Camps', 'Educator-led themed camps during school breaks, booked by the hour or by the day.', null, 'seasonal', null, null, null, null, null, '$25 for 1 hour · $45 for 2 · $60 for 3; day rate not listed', 'https://www.boogles.app/schedule', 6);
insert into public.place_programs (id, place_id, source_url, source_checked_date, verification_status, conflict_note, name, description, attendance, cadence, schedule_note, starts_on, ends_on, age_min, age_max, price_note, registration_url, sort_order)
values (md5('PE-002:program:pe002-specials')::uuid, 'PE-002', 'https://www.boogles.app/schedule', '2026-10-24', 'verified', null, 'Themed specials', 'Holiday sessions appear on the schedule. For Halloween 2026: Monster Palooza (Stay + Play for all ages, included with Stay + Play admission, booking required), Friendly Monster Adventure (ages 2–6, stay or drop off) and evening drop-off dance parties for 18 months to 8 (regular drop-off prices).', null, 'seasonal', null, null, null, null, null, null, 'https://www.boogles.app/schedule', 7);

