-- place_policies
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:age_guidance:0')::uuid, 'PE-002', 'https://www.boogles.ca/location/square-one-shopping-centre/', '2026-10-24', 'verified', null, 'age_guidance', 'The playhouse is designed for children 18 months to 8 years; Stay + Play and baby sessions welcome younger children.', 0);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:supervision:1')::uuid, 'PE-002', 'https://www.boogles.app/schedule', '2026-10-24', 'verified', null, 'supervision', 'Stay + Play: a parent or caregiver stays inside the playhouse the whole time.', 1);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:supervision:2')::uuid, 'PE-002', 'https://www.boogles.ca/services/', '2026-10-24', 'verified', null, 'supervision', 'Drop-off: you can leave the playhouse, but you must stay inside Square One.', 2);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:booking_rule:3')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'booking_rule', 'Create a Boogles account and family profile, then book your session online.', 3);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:other:4')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'other', 'Booking ahead is recommended. Some walk-in spots are kept each day; if a session is full online, watch for cancellations or call.', 4);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:other:5')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'other', 'Need longer at drop-off? Add time while your child is there by calling or booking online.', 5);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:other:6')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'other', 'Pay online or in person. Booking drop-off online needs no card; you pay at check-in.', 6);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:other:7')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'other', 'Anyone listed on your family profile can bring your child to a session in your place.', 7);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:dress_socks:8')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'dress_socks', 'Children don''t need to be toilet trained: pack diapers and a change of clothes (or just a change of clothes if they''re potty trained).', 8);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:food_rule:9')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'food_rule', 'Drop-off snacks are allergen-friendly (such as fruit, yogurt and organic chips) and cost $3; approve them when you register, or staff will ask you first.', 9);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:arrival:10')::uuid, 'PE-002', 'https://www.boogles.app/schedule', '2026-10-24', 'verified', null, 'arrival', 'A Stay + Play session''s 2 hours start when you check in.', 10);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:arrival:11')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'arrival', 'Only adults listed in your family profile can pick up from drop-off, and they need valid ID.', 11);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:arrival:12')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'arrival', 'First drop-off and your child is nervous? You''re welcome to stay a few minutes while they settle in.', 12);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:cancellation:13')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'cancellation', 'Drop-off: cancel up to 2 hours before at no charge; after that there''s a $10 fee.', 13);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:cancellation:14')::uuid, 'PE-002', 'https://www.boogles.ca/memberships/', '2026-10-24', 'verified', null, 'cancellation', 'Memberships renew monthly unless cancelled in advance. Payments aren''t refunded once a month starts, and unused hours, visits and class credits don''t carry over.', 14);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:hours_note:15')::uuid, 'PE-002', 'https://www.boogles.app/schedule', '2026-10-24', 'verified', null, 'hours_note', 'Everything is a booked session, and times change from day to day. Check the live schedule before you go.', 15);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:hours_note:16')::uuid, 'PE-002', 'https://www.boogles.app/schedule', '2026-10-24', 'verified', null, 'hours_note', 'In the week we checked (Oct 24–31, 2026), sessions ran every day, between 10 am and 8 pm.', 16);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:location_note:17')::uuid, 'PE-002', 'https://www.boogles.ca/location/square-one-shopping-centre/', '2026-10-24', 'verified', null, 'location_note', 'Lower level, next to the Food District and near Indigo.', 17);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:location_note:18')::uuid, 'PE-002', 'https://www.boogles.ca/locations/', '2026-10-24', 'verified', null, 'location_note', 'Boogles also has playhouses at Upper Canada Mall (Newmarket) and Hillcrest Mall (Richmond Hill).', 18);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:other:19')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'other', 'Late pickup from drop-off costs $5 for every 10 minutes.', 19);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:booking_rule:20')::uuid, 'PE-002', 'https://www.boogles.ca/service/drop-off-play/', '2026-10-24', 'verified', null, 'booking_rule', 'Using bundle or membership hours? Buy them before you book the session.', 20);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:other:21')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'other', 'For staff-to-child ratios at drop-off, the venue says it follows Canada''s licensed daycare guidelines; it doesn''t publish a number.', 21);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:other:22')::uuid, 'PE-002', 'https://www.boogles.ca/about/', '2026-10-24', 'verified', null, 'other', 'Play Partners are registered early childhood educators and assistants; the venue says they hold clear police vulnerable sector checks and current first aid and CPR.', 22);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:other:23')::uuid, 'PE-002', 'https://www.boogles.ca/about/', '2026-10-24', 'verified', null, 'other', 'Founded by a mom of two with a Montessori background.', 23);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:other:24')::uuid, 'PE-002', 'https://www.boogles.ca/gift-cards/', '2026-10-24', 'verified', null, 'other', 'Gift cards come in any amount, never expire and arrive by email; use them for drop-off, Stay + Play, classes, camps or the store.', 24);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:party:25')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'party', 'Every birthday gets the playhouse to yourselves for 2 hours, with dedicated Play Partners; setup and cleanup are included.', 25);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:party:26')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'party', 'Up to 50 guests for a private event.', 26);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:party:27')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'party', 'Pick a theme (art, music and movement, sensory play, slime-making or storytime) or ask for your own.', 27);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:party:28')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'party', 'Bring your own food, or the team can arrange catering through Square One''s partners.', 28);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:party:29')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'party', 'Bring decorations such as banners and balloons; tell the team ahead, and they''ll help you set up in the 30 minutes before the party.', 29);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:party:30')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'party', 'Book by emailing hello@boogles.ca. A 50% deposit holds your date, and cancellations within 7 days aren''t refunded.', 30);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:party:31')::uuid, 'PE-002', 'https://www.boogles.ca/faqs/', '2026-10-24', 'verified', null, 'party', 'You can ask for an in-person or virtual tour before booking.', 31);
insert into public.place_policies (id, place_id, source_url, source_checked_date, verification_status, conflict_note, kind, body, sort_order)
values (md5('PE-002:policy:party:32')::uuid, 'PE-002', 'https://www.boogles.ca/boogles-social/', '2026-10-24', 'verified', null, 'party', 'Boogles Social brings play stations and Play Partners to weddings, showers and other events across the GTA: $395 for up to 2 hours with one Play Partner, or $695 with two (extra time $125 or $200 an hour).', 32);

